begin;
do $$
declare owner_id uuid; vol uuid; mid uuid:=gen_random_uuid();eid uuid:=gen_random_uuid();past uuid:=gen_random_uuid();dev uuid:=gen_random_uuid();devcode bigint;gid text;newgid text;op jsonb;failed boolean;joined timestamptz;
begin
 select id into owner_id from wellness_members where role='admin' and status='active' and not temporary_password limit 1;
 select id into vol from wellness_members where role='volunteer' and not temporary_password limit 1;
 if owner_id is null or vol is null then raise exception 'Need an existing admin and volunteer';end if;
 update wellness_members set status='active' where id=vol;
 perform wellness_admin_save(owner_id,'mission',jsonb_build_object('id',mid,'name','QA team rollback','kind','large','code','QA-'||upper(mid::text),'active',true,'notes','Rollback only'));
 insert into wellness_events(id,mission_id,name,starts,ends,location) values(eid,mid,'QA today',(now() at time zone 'Asia/Vientiane')::date,(now() at time zone 'Asia/Vientiane')::date,'QA location'),(past,mid,'QA past',(now() at time zone 'Asia/Vientiane')::date-1,(now() at time zone 'Asia/Vientiane')::date-1,'QA past');
 if wellness_can_access_day(vol,eid) then raise exception 'Unassigned access';end if;
 perform wellness_team_assign(owner_id,mid,array[vol],true);
 select joined_at into joined from wellness_mission_members where mission_id=mid and user_id=vol;
 perform wellness_team_assign(owner_id,mid,array[vol],true);
 if joined<>(select joined_at from wellness_mission_members where mission_id=mid and user_id=vol) then raise exception 'Retry reset joining time';end if;
 if not wellness_can_access_day(vol,eid) or wellness_can_access_day(vol,past) then raise exception 'Joining date access failure';end if;
 perform wellness_attendance_save(owner_id,eid,jsonb_build_array(jsonb_build_object('user_id',vol,'status','present')));
 perform wellness_attendance_save(owner_id,eid,jsonb_build_array(jsonb_build_object('user_id',vol,'status','absent')));
 if (select status from wellness_attendance where user_id=vol and event_id=eid)<>'absent' then raise exception 'Attendance correction failed';end if;
 failed:=false;begin perform wellness_member_save(vol,vol,'admin','active');exception when others then failed:=true;end;if not failed then raise exception 'Volunteer self-promotion';end if;
 failed:=false;begin perform wellness_team_assign(vol,mid,array[owner_id],true);exception when others then failed:=true;end;if not failed then raise exception 'Volunteer changed roster';end if;
 failed:=false;begin perform wellness_attendance_save(vol,eid,'[]');exception when others then failed:=true;end;if not failed then raise exception 'Volunteer changed attendance';end if;
 perform wellness_member_save(owner_id,vol,'admin','active');if not wellness_can_access_day(vol,past) then raise exception 'Admin history unavailable';end if;
 perform wellness_member_save(owner_id,vol,'volunteer','active');
 failed:=false;begin perform wellness_member_save(owner_id,owner_id,'volunteer','active');exception when others then failed:=true;end;if not failed then raise exception 'Self-lockout permitted';end if;
 insert into wellness_devices(id,user_id,prefix,label) values(dev,vol,'QT','QA rollback') returning code into devcode;
 gid:='QT-'||lpad(devcode::text,4,'0')||'-000001-X';newgid:='QT-'||lpad(devcode::text,4,'0')||'-000002-X';
 op:=jsonb_build_object('id',gen_random_uuid(),'event_id',eid,'device_id',dev,'guest_id',gid,'station','registration','data',jsonb_build_object('name','Fictional QA','person_id',gid),'base_revision',null,'captured_at',now(),'date_ack',true);
 perform wellness_apply(vol,op);
 update wellness_records set created_at=joined-interval '1 second' where event_id=eid;
 failed:=false;begin perform wellness_apply(vol,op||jsonb_build_object('id',gen_random_uuid(),'station','dental','data',jsonb_build_object('status','Completed')));exception when others then failed:=true;end;if not failed then raise exception 'Old guest visit accepted';end if;
 failed:=false;begin perform wellness_apply(vol,op||jsonb_build_object('id',gen_random_uuid(),'guest_id',newgid));exception when others then failed:=true;end;if not failed then raise exception 'Old profile link accepted';end if;
 failed:=false;begin perform wellness_apply(vol,op||jsonb_build_object('id',gen_random_uuid(),'event_id',past));exception when others then failed:=true;end;if not failed then raise exception 'Past day write accepted';end if;
 perform wellness_team_assign(owner_id,mid,array[vol],false);
 if wellness_can_access_day(vol,eid) then raise exception 'Removed team member still has access';end if;
 if not exists(select 1 from wellness_attendance where event_id=eid and user_id=vol) then raise exception 'Removing team lost attendance';end if;
 failed:=false;begin perform wellness_ticket_context(vol,mid);exception when others then failed:=true;end;if not failed then raise exception 'Removed member got ticket ranges';end if;
 if has_table_privilege('authenticated','wellness_attendance','select') or has_function_privilege('anon','wellness_member_save(uuid,uuid,text,text)','execute') or has_function_privilege('authenticated','wellness_find_account(text)','execute') then raise exception 'Private controls exposed';end if;
end $$;
select 'PASS: role changes, self-escalation denial, joining-date restrictions, roster retries/removal, attendance, old guest/profile write denial and private RPCs' result;
rollback;
